tasks.for:
('grow.tend' in viewer.grants and (item.state = 'offered' or (item.state = 'taken' and item.performer = viewer.member))) ? (
  $ownMember := viewer.member;
  $currentScope := scope;
  $roomRows := reads.site.sources.room[fields.scope = $currentScope];
  $ownEvents := reads.presence.sources.events[fields.actor = $ownMember];
  $ownArrivals := $ownEvents[type = 'arrive'];
  $lastArrival := $ownArrivals[id = $max($ownArrivals.id)];
  $count($roomRows) = 1 ? (
    $count($lastArrival) = 1 ? (
      $lastArrival.fields.room = $roomRows.id and $count($ownEvents[type = 'leave' and fields.room = $roomRows.id and id > $lastArrival.id]) = 0
    ) : ($count($ownEvents[type = 'leave' and fields.room = $roomRows.id]) > 0 ? false : null)
  ) : null
) : false
